#!/usr/bin/env python3
"""Build a standalone, searchable HTML viewer of all Gemini responses."""
from pathlib import Path
import collections,json
ROOT=Path(__file__).resolve().parents[1]/'repeated-runs'/'2026-10-14'
bench=json.loads((ROOT/'benchmark.json').read_text())
rows=[]
for path in sorted((ROOT/'results'/'gemini-4-argon').glob('run-*.jsonl')):
 for line in path.read_text().splitlines():
  x=json.loads(line)
  item=next(i for i in bench['tests'][x['instrument']]['items'] if i['id']==x['item_id'])
  rows.append({'run':x['run'],'instrument':x['instrument'],'item':x['item_id'],'question':item['text'],'answer':x.get('content',''),'status':x['status'],'strict_rating':x.get('strict_rating'),'legacy_rating':x.get('rating'),'prompt':x['request']['messages'][0]['content'],'returned_model':x.get('returned_model'),'provider':x.get('provider'),'timestamp':x['finished_at']})
assert len(rows)==280 and len({(x['run'],x['instrument'],x['item']) for x in rows})==280
counts=collections.Counter(x['status'] for x in rows);assert counts=={'numeric':155,'non_strict_numeric':47,'non_numeric':78}
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gemini Argon — Original MoralityBench Answers</title>
<style>body{font:17px/1.6 system-ui,sans-serif;background:#faf9f6;color:#292524;max-width:1000px;margin:0 auto;padding:24px}h1{line-height:1.2}a{color:#9a3412}header,.card{background:white;border:1px solid #e7e5e4;border-radius:12px;padding:22px;margin-bottom:20px}.notice{background:#fff7ed;border-left:5px solid #c2410c;padding:18px}.controls{display:flex;flex-wrap:wrap;gap:14px;position:sticky;top:0;background:#faf9f6;padding:12px 0;z-index:2}label{display:flex;flex-direction:column;font-size:14px;font-weight:600}select,input{font:inherit;padding:9px;border:1px solid #a8a29e;border-radius:6px;background:white}.meta{font-size:14px;color:#57534e}.badge{display:inline-block;border-radius:6px;padding:3px 9px;font-size:14px;font-weight:600;background:#e7e5e4}.numeric{background:#dcfce7}.non_strict_numeric{background:#ffedd5}.non_numeric{background:#fee2e2}.answer{white-space:pre-wrap;overflow-wrap:anywhere;font:16px/1.7 system-ui}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}#count{font-weight:600}h2{font-size:20px}button{font:inherit}footer{padding:20px 0}</style>
<header><p><a href="https://moralitybench.ai">← MoralityBench</a> · <a href="https://github.com/FreecaseAI/moralitybench-data/tree/master/repeated-runs/2026-10-14">Raw data and analysis</a></p><h1>Gemini Argon’s original answers</h1><p>All <strong>280 responses</strong>: 56 questions × five fresh runs, October 14, 2026. Exact response text is retained below.</p><div class="notice"><strong>Why 47 answers are excluded.</strong> The instructions asked for one numeric self-rating, without reasoning or arguing that the questions do not apply. In these 47 responses Gemini instead described what other ethical frameworks would rate; 42 explicitly declined to give its own rating. Numbers such as “Deontological Ethics (Rating 8–9)” are not Gemini’s answer. Strict scoring excludes them.</div><p><strong>155 valid integers</strong> · <strong>47 verbose responses with misleading digits</strong> · <strong>78 responses without a usable numeric answer</strong>. The published result uses 155/280 answers and marks 125 missing. Higher agreement over the answered subset does not establish overall reliability.</p><p>Initially showing the 47 verbose responses. Select <em>All responses</em> to inspect every answer.</p></header>
<div class="controls"><label>Answer type<select id="type"><option value="non_strict_numeric">Other frameworks’ ratings — 47</option><option value="all">All responses — 280</option><option value="numeric">Valid numeric answers — 155</option><option value="non_numeric">No usable numeric answer — 78</option></select></label><label>Run<select id="run"><option value="all">All five runs</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></label><label>Questionnaire<select id="instrument"><option value="all">Both questionnaires</option><option>MFQ-2</option><option>EPQ</option></select></label><label>Search question or answer<input id="search" type="search" placeholder="e.g. Deontological"></label></div><p id="count" aria-live="polite"></p><main id="answers"></main><footer>Responses are evidence of this elicitation protocol, not a measure of moral correctness. Full prompts and source identities are expandable on each card.</footer>
<script id="records" type="application/json">__RECORDS__</script><script>
const rows=JSON.parse(document.getElementById('records').textContent);
const types={numeric:'Valid whole-answer integer',non_strict_numeric:'Other frameworks’ ratings — excluded',non_numeric:'No usable numeric answer — excluded'};
function node(tag,text,klass){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(klass)n.className=klass;return n;}
function render(){const t=document.getElementById('type').value,r=document.getElementById('run').value,i=document.getElementById('instrument').value,q=document.getElementById('search').value.toLowerCase();const selected=rows.filter(x=>(t==='all'||x.status===t)&&(r==='all'||String(x.run)===r)&&(i==='all'||x.instrument===i)&&(!q||(x.question+' '+x.answer).toLowerCase().includes(q)));document.getElementById('count').textContent=selected.length+' of 280 responses shown';const host=document.getElementById('answers');host.replaceChildren();for(const x of selected){const card=node('article',undefined,'card');card.id='run-'+x.run+'-'+x.instrument+'-'+x.item;card.append(node('p','Run '+x.run+' · '+x.instrument+' · Question '+x.item,'meta'),node('h2',x.question),node('span',types[x.status], 'badge '+x.status));if(x.strict_rating!==null)card.append(node('p','Scored rating: '+x.strict_rating));else if(x.legacy_rating!==null)card.append(node('p','Old parser extracted '+x.legacy_rating+'; excluded from strict scoring.','meta'));card.append(node('p','Gemini’s complete response:'),node('div',x.answer,'answer'));const d=node('details');d.append(node('summary','Exact prompt and source'),node('pre',x.prompt),node('p','Returned model: '+x.returned_model+' · Provider: '+x.provider+' · '+x.timestamp,'meta'));card.append(d);host.append(card);}}
for(const id of ['type','run','instrument'])document.getElementById(id).addEventListener('change',render);document.getElementById('search').addEventListener('input',render);render();
</script></html>'''
serialized=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
page=page.replace('__RECORDS__',serialized)
(ROOT/'gemini-answers.html').write_text(page)
print('Built standalone Gemini viewer:280 complete responses;47 initially displayed.')
